def top_words(text, n=5):
    """The n most common words, most common first, ties alphabetical."""
    counts = {}
    for word in words(text):
        if word in counts:
            counts[word] = counts[word] + 1
        else:
            counts[word] = 1
    ranked = []
    for word in counts:
        ranked.append((-counts[word], word))
    ranked.sort()
    result = []
    for negative_count, word in ranked[:n]:
        result.append((word, -negative_count))
    return result


def _positive_int(value):
    number = int(value)
    if number < 1:
        raise argparse.ArgumentTypeError(f"must be >= 1, got {value}")
    return number


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("path", help="the text file to read")
    parser.add_argument(
        "--top",
        type=_positive_int,
        default=5,
        help="how many words to print (default: 5)",
    )
    args = parser.parse_args(argv)
    with open(args.path, encoding="utf-8") as handle:
        text = handle.read()
    for word, count in top_words(text, args.top):
        print(f"{count:>5}  {word}")
    return 0
